// 前端用 formData.append('images', file) 上傳，可能多張同名欄位。
// 這裡把每個 binary property 攤平成獨立 item，並轉成 base64 給 Claude 視覺 API 用。
// 注意：getBinaryDataBuffer 的呼叫方式在不同 n8n 版本略有差異，
// 若這行報錯，改用 this.helpers.getBinaryDataBuffer(itemIndex, propertyName)。
const inputItems = $input.all();
const result = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  const binaryKeys = Object.keys(item.binary || {});
  for (const key of binaryKeys) {
    const buffer = await $helpers.getBinaryDataBuffer(i, key);
    const meta = item.binary[key];
    result.push({
      json: {
        fileName: meta.fileName || key,
        mimeType: meta.mimeType || 'image/jpeg',
        base64: buffer.toString('base64'),
      },
    });
  }
}

if (result.length === 0) {
  throw new Error('沒有收到任何圖片，請確認前端有用 images 欄位上傳檔案');
}

return result;

