// 把每張圖片的 Claude 回覆解析成 JSON，合併成單一 { poNumber, items } 回傳給前端
const inputItems = $input.all();
let poNumber = '';
let allItems = [];

for (const item of inputItems) {
  const raw = item.json?.content?.[0]?.text || '';
  const cleaned = raw.replace(/```json|```/g, '').trim();
  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    continue; // 這張圖辨識失敗就跳過，不整個報錯
  }
  if (parsed.poNumber && !poNumber) poNumber = parsed.poNumber;
  if (Array.isArray(parsed.items)) allItems = allItems.concat(parsed.items);
}

return [{ json: { poNumber, items: allItems } }];
